import type { ParamValue, TemplateManifest } from "../types/template";
import type { Word } from "../types/project";

/** public/templates/index.json is generated by scripts/build-template-index.mjs */
export async function loadTemplateIndex(): Promise<TemplateManifest[]> {
  const res = await fetch("/templates/index.json");
  if (!res.ok) throw new Error(`templates/index.json: HTTP ${res.status} (run "npm run templates:index")`);
  return (await res.json()) as TemplateManifest[];
}

/** Manifest defaults merged under the clip's own params. */
export function withDefaults(
  manifest: TemplateManifest | undefined,
  params: Record<string, ParamValue>,
): Record<string, ParamValue> {
  const out: Record<string, ParamValue> = {};
  if (manifest) {
    for (const [key, spec] of Object.entries(manifest.params)) {
      if (spec.default !== undefined) out[key] = spec.default;
    }
  }
  return { ...out, ...params };
}

export interface TemplateUrlInput {
  id: string;
  params: Record<string, ParamValue>;
  theme: Record<string, string>;
  /** clip duration in seconds */
  duration: number;
  /** words in the clip window, times relative to clip start (only if the template needs them) */
  words?: Word[];
}

/** Runtime contract: docs/TEMPLATE_CONTRACT.md (query params p, theme, d, w). */
export function buildTemplateUrl(input: TemplateUrlInput): string {
  const q = new URLSearchParams();
  q.set("p", JSON.stringify(input.params));
  q.set("theme", JSON.stringify(input.theme));
  q.set("d", String(input.duration));
  if (input.words) q.set("w", JSON.stringify(input.words));
  return `/templates/${input.id}/index.html?${q.toString()}`;
}

/** Shape of the globals a template exposes on its window. */
export interface TemplateWindow extends Window {
  __seek?: (t: number) => void;
  __ready?: Promise<void>;
}
